def largest_digit_sum_pair(nums):
    best = {}
    answer = -1
    for x in nums:
        key = sum(int(c) for c in str(x))
        if key in best:
            answer = max(answer, best[key] + x)
        best[key] = max(best.get(key, 0), x)
    return answer

